    WHERE pw.word_id = '3100100101' AND p.language_id = (SELECT id FROM language WHERE code = 'yue') AND p.deleted_at IS NULL
  )
  RETURNING id
)
INSERT INTO phrase_word (phrase_id, word_id) SELECT id, '3100100101' FROM np ON CONFLICT DO NOTHING;
